<script setup lang="ts">
import type { Prospect, ProspectSettings } from '~/types/prospecting'
import { prospectsInPeriod } from '~/utils/prospecting-workspace'
import { localDay, addDays, contactCounted, responseCounted, interestCounted, segmentResults } from '~/utils/prospecting'
const props = defineProps<{ leads: Prospect[]; settings: ProspectSettings }>()
const period = ref('all')
const from = ref('')
const to = ref('')
function changePeriod() {
  const today = localDay()
  if (period.value === 'all') { from.value = ''; to.value = '' }
  else if (period.value === 'week') { const day = new Date(today + 'T12:00:00').getDay(); from.value = addDays(today, -(day === 0 ? 6 : day - 1)); to.value = today }
  else if (period.value === 'month') { from.value = today.slice(0, 8) + '01'; to.value = today }
}
const invalidPeriod = computed(() => !!from.value && !!to.value && from.value > to.value)
const periodLeads = computed(() => prospectsInPeriod(props.leads, from.value, to.value))
const registered = computed(() => invalidPeriod.value ? 0 : props.leads.filter(lead => (!from.value || localDay(new Date(lead.createdAt)) >= from.value) && (!to.value || localDay(new Date(lead.createdAt)) <= to.value)).length)
const periodWon = computed(() => periodLeads.value.filter(lead => lead.stage === 'Fechado' && ((!from.value && !to.value) || lead.history.some(item => item.stage === 'Fechado'))))
const allContacted = computed(() => props.leads.filter(contactCounted).length)
const results = computed(() => segmentResults(periodLeads.value.map(lead => lead.stage === 'Fechado' && !periodWon.value.some(won => won.id === lead.id) ? { ...lead, stage: 'Proposta enviada' as const } : lead)))
const funnel = computed(() => [{ name: 'Cadastradas no período', count: registered.value }, { name: 'Contatadas', count: periodLeads.value.filter(contactCounted).length }, { name: 'Responderam', count: periodLeads.value.filter(responseCounted).length }, { name: 'Interessadas', count: periodLeads.value.filter(interestCounted).length }, { name: 'Fechadas', count: periodWon.value.length }])
const contacted = computed(() => periodLeads.value.filter(contactCounted).length)
const won = periodWon
const money = (value: number) => value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })
</script>
<template>
  <div class="space-y-7"><section class="rounded-2xl border bg-white p-5"><div class="flex flex-wrap items-end gap-4"><label class="text-sm">Período<select v-model="period" class="mt-2 block min-h-11 rounded-lg border px-3" @change="changePeriod"><option value="all">Todo o histórico</option><option value="week">Esta semana</option><option value="month">Este mês</option><option value="custom">Personalizado</option></select></label><template v-if="period !== 'all'"><label class="text-sm">De<input v-model="from" type="date" class="mt-2 block min-h-11 rounded-lg border px-3" @change="period = 'custom'"></label><label class="text-sm">Até<input v-model="to" type="date" class="mt-2 block min-h-11 rounded-lg border px-3" @change="period = 'custom'"></label></template></div><p v-if="invalidPeriod" role="alert" class="mt-3 text-sm text-rose-700">A data final deve ser igual ou posterior à inicial.</p><p class="mt-3 text-xs leading-6 text-slate-500">Cadastros pela data de criação; contatos, respostas e interesse pelas interações no período, mesmo de empresas cadastradas antes. Fechamentos consideram empresas atualmente fechadas com registro de fechamento no período. O investimento informado é o total de todo o histórico.</p></section><div class="grid gap-6 lg:grid-cols-[1fr_1.2fr]"><section class="rounded-2xl border border-slate-200 bg-white p-6"><p class="text-xs uppercase tracking-widest text-slate-500">Da seleção à venda</p><h2 class="mt-3 text-xl font-semibold">Atividade comercial no período</h2><div class="mt-7 space-y-5"><div v-for="item in funnel" :key="item.name"><div class="mb-2 flex justify-between text-sm"><span>{{ item.name }}</span><strong>{{ item.count }}</strong></div><div class="h-2 overflow-hidden rounded-full bg-slate-100"><div class="h-full rounded-full bg-[#2458df]" :style="{ width: `${Math.max(...funnel.map(step => step.count), 1) ? item.count / Math.max(...funnel.map(step => step.count), 1) * 100 : 0}%` }" /></div></div></div><p class="mt-6 text-xs leading-6 text-slate-500">Cada empresa conta uma vez por indicador, incluindo arquivadas. Os indicadores podem representar empresas diferentes; respostas deste período podem vir de contatos anteriores.</p></section><section class="rounded-2xl bg-[#14243e] p-6 text-white"><p class="text-xs uppercase tracking-widest text-blue-200">Resultado financeiro registrado</p><h2 class="mt-3 text-xl font-semibold">Projeto e recorrência separados</h2><div class="mt-8 grid gap-7 sm:grid-cols-2"><div><p class="text-xs text-slate-300">Projetos fechados</p><p class="mt-2 text-3xl font-semibold">{{ money(won.reduce((sum, lead) => sum + lead.proposalValue, 0)) }}</p></div><div><p class="text-xs text-slate-300">Mensalidade contratada</p><p class="mt-2 text-3xl font-semibold">{{ money(won.reduce((sum, lead) => sum + lead.monthlyValue, 0)) }}</p></div><div><p class="text-xs text-slate-300">Investimento total informado</p><p class="mt-2 text-2xl">{{ money(settings.budget) }}</p></div><div><p class="text-xs text-slate-300">Custo por contatada · todo o histórico</p><p class="mt-2 text-2xl">{{ allContacted ? money(settings.budget / allContacted) : '—' }}</p></div></div><p class="mt-8 border-t border-white/20 pt-5 text-xs leading-6 text-slate-300">Valores informados por você, sem confirmação de pagamento. Mensalidade não é somada ao valor dos projetos. Não há previsão automática de retorno.</p></section></div>
    <section class="overflow-hidden rounded-2xl border border-slate-200 bg-white"><div class="p-6"><p class="text-xs uppercase tracking-widest text-slate-500">Aprenda antes de ampliar o investimento</p><h2 class="mt-3 text-xl font-semibold">Quais segmentos estão respondendo?</h2></div><div class="overflow-x-auto" tabindex="0" role="region" aria-label="Resultados por segmento"><table class="w-full min-w-[680px] text-left text-sm"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th class="p-4" scope="col">Segmento</th><th class="p-4" scope="col">Contatadas</th><th class="p-4" scope="col">Respostas</th><th class="p-4" scope="col">Interessadas</th><th class="p-4" scope="col">Fechadas</th><th class="p-4" scope="col">Taxa de resposta</th></tr></thead><tbody><tr v-for="row in results" :key="row.segment" class="border-t border-slate-100"><th scope="row" class="p-4 font-medium">{{ row.segment }}</th><td class="p-4">{{ row.contacted }}</td><td class="p-4">{{ row.responses }}</td><td class="p-4">{{ row.interested }}</td><td class="p-4">{{ row.won }}</td><td class="p-4">{{ row.contacted ? `${row.rate}%` : '—' }}</td></tr></tbody></table></div><p v-if="!results.length" class="p-7 text-sm text-slate-500">Cadastre empresas e registre suas abordagens para comparar os segmentos.</p><p class="border-t p-5 text-xs leading-6 text-slate-500">Taxa de resposta = empresas que responderam ÷ empresas contatadas. Amostras pequenas servem como aprendizado, não como garantia de desempenho.</p></section></div>
</template>
